#!/bin/sh
# Generated by qr-deploy.
#
# PLAT-003 creates the Patroni cluster; this job creates the four logical
# databases and eight roles before db-bootstrap.sh and migrate.sh. It connects
# as the superuser through the `postgres`/HAProxy endpoint. The superuser
# password is a mode-600 file; the eight role passwords are read from the owner
# and app URL files inside the container, never from an argument or a log.
set -eu
OVERLAY=quantrule
IMAGE=postgres@sha256:dc184ed86a2b6421fd5ea1bf2ffa3d6e9f1df86796bf0830a7476eb064a186ff
CA=pki/database-ca.crt

fail() {
    printf 'qr-deploy cluster-bootstrap: %s\n' "$*" >&2
    exit 1
}

[ -f "$CA" ] || fail "missing $CA"
for name in postgres_superuser_password gateway_owner_database_url gateway_database_url data_owner_database_url data_database_url evidence_owner_database_url evidence_database_url simulation_owner_database_url simulation_database_url; do
    [ -f "secrets/$name" ] || fail "missing secrets/$name"
done

docker run --rm -i --network "$OVERLAY" \
    -e PGHOST=postgres \
    -e PGPORT=5432 \
    -e PGUSER=postgres \
    -e PGDATABASE=postgres \
    -e PGSSLMODE=verify-full \
    -e PGSSLROOTCERT=/run/pki/database-ca.crt \
    -e QR_SUPERUSER_PASSWORD_FILE=/run/secrets/postgres_superuser_password \
    -e PGPASSFILE=/tmp/pgpass \
    -v "$PWD/$CA:/run/pki/database-ca.crt:ro" \
    -v "$PWD/secrets/postgres_superuser_password:/run/secrets/postgres_superuser_password:ro" \
    -v "$PWD/secrets/gateway_owner_database_url:/run/secrets/gateway_owner_database_url:ro" \
    -v "$PWD/secrets/gateway_database_url:/run/secrets/gateway_database_url:ro" \
    -v "$PWD/secrets/data_owner_database_url:/run/secrets/data_owner_database_url:ro" \
    -v "$PWD/secrets/data_database_url:/run/secrets/data_database_url:ro" \
    -v "$PWD/secrets/evidence_owner_database_url:/run/secrets/evidence_owner_database_url:ro" \
    -v "$PWD/secrets/evidence_database_url:/run/secrets/evidence_database_url:ro" \
    -v "$PWD/secrets/simulation_owner_database_url:/run/secrets/simulation_owner_database_url:ro" \
    -v "$PWD/secrets/simulation_database_url:/run/secrets/simulation_database_url:ro" \
    "$IMAGE" sh -eu -c '
        printf "postgres:5432:*:postgres:%s\n" "$(cat "$QR_SUPERUSER_PASSWORD_FILE")" > "$PGPASSFILE"
        chmod 600 "$PGPASSFILE"
        exec psql -v ON_ERROR_STOP=1 -q -f -
    ' <<'SQL'
\set gateway_owner_password `sed -n 's|^[^:]*://[^:]*:\([^@]*\)@.*$|\1|p' /run/secrets/gateway_owner_database_url | tr -d '\n'`
\set gateway_app_password `sed -n 's|^[^:]*://[^:]*:\([^@]*\)@.*$|\1|p' /run/secrets/gateway_database_url | tr -d '\n'`
\set catalog_owner_password `sed -n 's|^[^:]*://[^:]*:\([^@]*\)@.*$|\1|p' /run/secrets/data_owner_database_url | tr -d '\n'`
\set catalog_app_password `sed -n 's|^[^:]*://[^:]*:\([^@]*\)@.*$|\1|p' /run/secrets/data_database_url | tr -d '\n'`
\set evidence_owner_password `sed -n 's|^[^:]*://[^:]*:\([^@]*\)@.*$|\1|p' /run/secrets/evidence_owner_database_url | tr -d '\n'`
\set evidence_app_password `sed -n 's|^[^:]*://[^:]*:\([^@]*\)@.*$|\1|p' /run/secrets/evidence_database_url | tr -d '\n'`
\set simulation_owner_password `sed -n 's|^[^:]*://[^:]*:\([^@]*\)@.*$|\1|p' /run/secrets/simulation_owner_database_url | tr -d '\n'`
\set simulation_app_password `sed -n 's|^[^:]*://[^:]*:\([^@]*\)@.*$|\1|p' /run/secrets/simulation_database_url | tr -d '\n'`

SELECT format('CREATE ROLE %I LOGIN', 'qr_gateway_owner')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'qr_gateway_owner')
\gexec
ALTER ROLE qr_gateway_owner WITH LOGIN PASSWORD :'gateway_owner_password';
SELECT format('CREATE ROLE %I LOGIN', 'qr_gateway_app')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'qr_gateway_app')
\gexec
ALTER ROLE qr_gateway_app WITH LOGIN PASSWORD :'gateway_app_password';
SELECT format('CREATE ROLE %I LOGIN', 'qr_catalog_owner')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'qr_catalog_owner')
\gexec
ALTER ROLE qr_catalog_owner WITH LOGIN PASSWORD :'catalog_owner_password';
SELECT format('CREATE ROLE %I LOGIN', 'qr_catalog_app')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'qr_catalog_app')
\gexec
ALTER ROLE qr_catalog_app WITH LOGIN PASSWORD :'catalog_app_password';
SELECT format('CREATE ROLE %I LOGIN', 'qr_evidence_owner')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'qr_evidence_owner')
\gexec
ALTER ROLE qr_evidence_owner WITH LOGIN PASSWORD :'evidence_owner_password';
SELECT format('CREATE ROLE %I LOGIN', 'qr_evidence_app')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'qr_evidence_app')
\gexec
ALTER ROLE qr_evidence_app WITH LOGIN PASSWORD :'evidence_app_password';
SELECT format('CREATE ROLE %I LOGIN', 'qr_simulation_owner')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'qr_simulation_owner')
\gexec
ALTER ROLE qr_simulation_owner WITH LOGIN PASSWORD :'simulation_owner_password';
SELECT format('CREATE ROLE %I LOGIN', 'qr_simulation_app')
WHERE NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'qr_simulation_app')
\gexec
ALTER ROLE qr_simulation_app WITH LOGIN PASSWORD :'simulation_app_password';

SELECT format('CREATE DATABASE %I OWNER %I', 'qr_gateway', 'qr_gateway_owner')
WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = 'qr_gateway')
\gexec
ALTER DATABASE qr_gateway OWNER TO qr_gateway_owner;
SELECT format('CREATE DATABASE %I OWNER %I', 'qr_catalog', 'qr_catalog_owner')
WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = 'qr_catalog')
\gexec
ALTER DATABASE qr_catalog OWNER TO qr_catalog_owner;
SELECT format('CREATE DATABASE %I OWNER %I', 'qr_evidence', 'qr_evidence_owner')
WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = 'qr_evidence')
\gexec
ALTER DATABASE qr_evidence OWNER TO qr_evidence_owner;
SELECT format('CREATE DATABASE %I OWNER %I', 'qr_simulation', 'qr_simulation_owner')
WHERE NOT EXISTS (SELECT 1 FROM pg_database WHERE datname = 'qr_simulation')
\gexec
ALTER DATABASE qr_simulation OWNER TO qr_simulation_owner;

SQL
